function shortItemName(g){return({pfd:'救生衣',rod:'通用船竿',tackle:'单钩沉底',bait:'鱼饵盒',cooler:'冷藏箱',net:'抄网',descending_device:'降鱼器',water:'饮水用品',safety:'应急包',rod_light:'轻型船竿',rod_boat:'强韧船竿',rod_electric:'电轮套装',reel_smooth:'泄力轮',line_braid:'编织线',leader_heavy:'耐磨前导',rig_slider:'滑铅组',rig_jig:'软饵组',rig_float:'浮游组',rig_dropper:'双支线组',rig_sabiki:'羽毛组',rig_feather40:'双支羽毛',sinker_heavy:'铅坠包',bait_anchovy:'鳀鱼饵',bait_shrimp:'虾饵',bait_sardine:'沙丁鱼饵',bait_soft:'软饵',cooler_large:'大冷藏箱',nautical_chart:'纸海图',compass:'罗盘',gps:'GPS',sounder:'测深仪',anchor:'船锚',sea_anchor:'漂流伞'})[g.id]||g.name;}
