function openMap(){const s=sim.state,nav=sim.navigationInstruments(),p=s.mode==='walk'?{x:s.playerX,z:s.playerZ}:{x:s.boatX,z:s.boatZ};if(!nav.chart){openModal('map',heading('THE UNCHARTED MORNING','背包里还没有海图')+`<div class="instrument-empty">⌖</div><p class="modal-desc">在码头小屋兑换纸质海图，再从个人背包启用。</p><div class="button-row">${button('chart-gear',sim.atCounter?'查看商店':'打开背包',true)}</div>`);$('chart-gear').onclick=()=>openGear(sim.atCounter?'shop':'pack','other');return;}const range=spot=>nav.gps?`${formatDistance(compressedDistance(p,spot))} →`:'→';openModal('map',heading('MONTEREY BAY','折起的海图',`航程比例 1:2 · ${nav.gps?'GPS 已连接':'纸图不显示当前位置'}`)+`<canvas id="chart" class="map-canvas" width="540" height="240" aria-label="Santa Cruz 海岸与钓点"></canvas><div class="spot-list">${FISHING_SPOTS.map((spot,i)=>`<button class="spot-button" data-spot="${i}"><div><strong>${i+1}. ${spot.name}</strong><small>${seafloorAt(spot.x,spot.z).label}</small></div><span>${range(spot)}</span></button>`).join('')}<button id="return-dock" class="spot-button"><div><strong>↩ 返回码头小屋</strong><small>靠泊 · 兑换 · 补给</small></div><span>${range({x:HARBOR.returnX,z:HARBOR.returnZ})}</span></button></div><p class="credits-note">海岸轮廓 © OpenStreetMap contributors。底质参考 USGS 历史测绘：浅褐为沙底、深绿为裸岩、灰绿为混合底，蓝色区域资料空缺；未测区域不作填补。</p>`);drawChart();for(const el of document.querySelectorAll('[data-spot]'))el.onclick=()=>{const target=FISHING_SPOTS[Number(el.dataset.spot)];closeModal();feedback(sim.selectWaypoint(target));};$('return-dock').onclick=()=>{closeModal();feedback(sim.state.mode==='walk'?sim.walkTo('counter'):sim.selectWaypoint('dock'));};}
function drawChart(){const c=$('chart'),ctx=c.getContext('2d'),W=c.width,H=c.height;const bounds={minX:-2400,maxX:3900,minZ:-2200,maxZ:900},sx=W/(bounds.maxX-bounds.minX),sz=H/(bounds.maxZ-bounds.minZ),pt=(x,z)=>[(x-bounds.minX)*sx,(z-bounds.minZ)*sz];ctx.fillStyle='#32858a';ctx.fillRect(0,0,W,H);for(let py=0;py<H;py+=3)for(let px=0;px<W;px+=3){const bed=seafloorAt(bounds.minX+(px+1.5)/sx,bounds.minZ+(py+1.5)/sz);if(!bed.mapped)continue;ctx.fillStyle=({sand:'#9baf91',mud:'#7f9d88',mixed:'#648e7c',reef:'#356d61',artificial:'#6f8076'})[bed.kind]||'#32858a';ctx.fillRect(px,py,3,3);}ctx.strokeStyle='#9bd0bd22';ctx.lineWidth=1;for(let x=0;x<W;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}for(const rings of[landPolygons,pierRings])for(const ring of rings){ctx.beginPath();ring.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](...pt(p.x,p.z)));ctx.closePath();ctx.fillStyle=rings===pierRings?'#bc8867':'#d2ce9d';ctx.fill();}ctx.font='10px monospace';for(const [i,p]of FISHING_SPOTS.entries()){const[x,y]=pt(p.x,p.z);ctx.fillStyle='#fff1d5';ctx.fillRect(x-4,y-4,8,8);ctx.fillText(String(i+1),x+9,y+4);}const s=sim.state,pos=s.mode==='walk'?{x:s.playerX,z:s.playerZ}:{x:s.boatX,z:s.boatZ},[x,y]=pt(pos.x,pos.z);if(sim.navigationInstruments().gps){ctx.fillStyle='#f08d6d';ctx.fillRect(x-4,y-4,8,8);ctx.fillStyle='#fff1d5';ctx.fillText('YOU',x+9,y-3);}ctx.fillStyle='#fff1d5';ctx.fillText('SANTA CRUZ',20,23);ctx.fillStyle='#a6d4c4';ctx.fillText('MONTEREY BAY',W-115,H-17);}
function fishSprite(f){return sprites.fish[fishSpriteKind(f)];}
let catchArtTime=0;
function drawCatchArtwork(canvas,fish,compact=false){
 if(!canvas||!fish)return;
 const host=canvas.parentElement,baseWidth=compact?96:Math.max(160,Math.floor(host.clientWidth));
 const layout=drawFishArt(canvas,fishSprite(fish),fish,{width:baseWidth,height:compact?48:180,compact,animate:!compact,time:catchArtTime,energy:sim.state.fishFight?.energy??.6,reducedMotion:reducedMotion.matches});
 canvas.style.width=`${layout.width}px`;canvas.style.height=`${layout.height}px`;
 canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`${fishDisplayName(fish)}，${formatLength(fish.length)}，与英寸尺按同一比例显示`);
 canvas.dataset.fishLengthCm=String(fish.length);canvas.dataset.scaleCm=String(layout.pxPerCm);
}
function refreshCatchArtwork(){
 if(menu==='catch')drawCatchArtwork($('catch-art'),sim.state.fish);
 else if(menu==='journal')sim.state.catches.slice().reverse().forEach((f,i)=>drawCatchArtwork($(`journal-fish-${i}`),f,true));
}
function openCatch(){catchArtTime=0;const f=sim.state.fish;if(!f)return;openModal('catch',heading('A MOMENT TO REMEMBER',esc(f.name),`${fishCommonName(f)?`<strong class="fish-common-name">${esc(fishCommonName(f))}</strong><br>`:''}${esc(f.latin||'')}`)+`<div class="catch-hero" tabindex="0" aria-label="鱼获与英寸测量尺"><canvas id="catch-art"></canvas></div><div class="catch-stats"><div><strong>${formatNumber(cmToInches(f.length))}</strong><small>英寸 in</small></div><div><strong>${formatNumber(kgToPounds(f.kg),2)}</strong><small>磅 lb</small></div><div><strong>${Math.round(sim.state.fightTime)}</strong><small>收鱼用时</small></div></div><div class="button-row">${button('keep-fish','收入冰箱',true)}${button('release-fish','记录并放流')}</div>`);refreshCatchArtwork();$('keep-fish').onclick=()=>{const r=sim.keepCatch();feedback(r);if(r.ok){closeModal();persist();}};$('release-fish').onclick=()=>{feedback(sim.releaseCatch());closeModal();persist();};}
function openJournal(){const s=sim.state;openModal('journal',`<span class="balance">✦ ${s.profile.credits}</span>`+heading('THE DAYS WE KEEP','鱼获与航程',`下竿 ${s.casts} 次 · 鱼获 ${s.catches.length} 条`)+(s.catches.length?s.catches.slice().reverse().map((f,i)=>`<div class="catch-row"><div class="catch-thumbnail"><canvas id="journal-fish-${i}"></canvas></div><div><b>${esc(f.name)}</b>${fishCommonName(f)?`<small class="fish-common-name">${esc(fishCommonName(f))}</small>`:''}<small>${formatLength(f.length)} · ${formatWeight(f.kg)} · ${f.time}</small>${f.rig?.hookSize?`<small>钩号 ${esc(f.rig.hookSize)}</small>`:''}</div><span>${f.confiscated?'已没收':f.settled?'已记录':f.kept?'冰箱中':'已放流'}</span></div>`).join(''):'<p class="journal-empty">冰箱里还很安静。<br>好故事，总会从第一竿开始。</p>')+(s.profile.fineDebt?`<p class="credits-note">待缴罚款：${s.profile.fineDebt} 潮汐点；后续收入先抵扣。</p>`:'')+`<h3>航海手记</h3><div class="key-list">${s.journal.slice(0,10).map(j=>`${j.time}　${esc(formatLegacyCatchNote(j.text))}`).join('<br>')}</div>`);refreshCatchArtwork();}
function openSettings(){const m=marineSummary();openModal('settings',heading('SLOW DOWN, DROP A LINE','海风与设置')+`<div class="settings-grid">${button('settings-audio',`总声音：${audio.enabled?'开':'关'}`)}${button('settings-music',`轻快背景音乐：${audio.musicEnabled?'开':'关'}`)}${button('settings-photo','保存像素风景')}${started?button('settings-rescue','呼叫免费救援'):''}</div><div class="form-row"><label for="music-volume">音乐音量</label><input id="music-volume" type="range" min="0" max="1" step=".01" value="${audio.musicVolume}"></div><h3>操作</h3><p class="key-list">行走：轻点地面自动寻路 / WASD<br>操船：摆动握把转向，推拉右侧推杆控制前后挡与油门<br>中间是空挡，向上前进、向下倒车；越远油门越大<br>换向先回空挡并减速。松手保留握把与推杆位置<br>WASD 也可操船，键盘松手收油<br>手持鱼竿且停机：轻点水面定点抛投<br>船边垂直下放：点下放 / 空格<br>鱼讯自动进入第一视角；稳收鱼线可自然挂钩，拖动水面调整竿姿<br>鱼获处理完或脱钩后返回俯视地图<br>竿姿：上下拖动抬竿，左右拖动摆竿<br>摇轮：顺时针转鱼轮，或按住轮柄 / F；松开即停<br>购买并换用电轮船竿套装后，可点电动收线回收钓组<br>打开线杯放线，锁住线杯停放；中鱼后可拧动 ✳ 调整泄力<br>看竿弯、听泄力出线；小鱼稳收，大鱼冲刺时让线<br>E 互动 · R 引擎 · I 装备 · M 海图<br>轻提：调整竿姿 / 按住空格；摇轮将钓组收至船边<br>选择左/右舷竿架可慢速拖钓；咬钩后取竿<br>鱼竿与消耗品：切换预组装鱼竿，整套换装钓组、手动装饵<br>鱼饵与钓组会消耗；断线、挂底或鱼钩拉直后需更换备用钓组<br>钓组注明钩号：大钩不易进入小嘴，细小钩遇大鱼要让线<br>钩号、钩型与钩丝共同影响挂钩和持鱼；不同品牌同号尺寸不完全一致<br>GPS、测深仪：从背包里点选仪器查看<br>掌舵并携带海图时，点击水面可设置辅助航向。</p><h3>今天的海</h3><p class="credits-note">${m.label} · 风 ${formatWind(sea.windKnots)} · 浪 ${formatDepth(sea.waveHeight)} · 海温 ${formatTemperature(sea.waterTemp)}<br>观测时间：${m.observedAt?new Date(m.observedAt).toLocaleString('zh-CN',{timeZone:'America/Los_Angeles'}):'暂不可用'}（Santa Cruz）<br>区域浮标距离约 14–25 mi，非船边实测。<br>每次出发从 06:00 开始，游戏时间 2 倍速；外海航程比例 1:2。打开菜单时暂停。</p><p class="credits-note">原创 Canvas 像素美术 · 海岸数据 <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a> · <a href="https://www.ndbc.noaa.gov/station_page.php?station=46236" target="_blank" rel="noopener">NOAA 海况</a>。人物为虚构值班员。鱼获交易使用游戏积分。</p><details class="source-details"><summary>资料来源与模拟说明</summary><p class="credits-note">鱼种、水域与钓法参考 CDFW、NOAA 和 California Sea Grant。海底参考 USGS 历史测绘，资料空缺保留；码头局部使用有标记的文献近似。月份、饵料、钓组、水层与实际漂流共同影响鱼讯。鱼讯、季节权重与海上巡查概率为游戏参数，并非实测概率；返港必检，罚款使用游戏积分。挂钩由钩号、口型、钩型和持续受力决定；松口与脱钩概率按鱼种、松线和过载校准。钩门、口型与钩丝承载为模拟参数，不是实测跑鱼率。体型与游速参考官方资料和游泳研究；挂钩拉力、冲刺和疲劳是模拟近似，不是实测拉力。法规使用核实于 2026-09-27 的 2026 年快照，未知证据不判为违规。</p><p class="credits-note"><a href="https://doi.org/10.5066/F7TM785G" target="_blank" rel="noopener">USGS Santa Cruz 海底</a> · <a href="https://sanctuaries.noaa.gov/science/conservation/pdfs/halibut14.pdf" target="_blank" rel="noopener">NOAA 本地比目鱼钓法研究</a> · <a href="https://www.webapps.nwfsc.noaa.gov/assets/25/833_12022008_162813_RockfishSurveyTM95WebFinal.pdf" target="_blank" rel="noopener">NOAA 岩鱼钩号试验</a> · <a href="https://myfwc.com/fishing/basics/" target="_blank" rel="noopener">FWC 圆形钩与收线</a> · <a href="https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=34195" target="_blank" rel="noopener">CDFW 白海鲈钩口特征</a> · <a href="https://pubmed.ncbi.nlm.nih.gov/12847119/" target="_blank" rel="noopener">Bonito 游泳研究</a> · <a href="https://nrm.dfg.ca.gov/FileHandler.ashx?DocumentID=34151&inline=true" target="_blank" rel="noopener">CDFW 白海鲈体型</a> · <a href="https://wildlife.ca.gov/Fishing/Ocean/Regulations/Groundfish-Summary" target="_blank" rel="noopener">CDFW 底栖鱼规定</a> · <a href="https://wildlife.ca.gov/Fishing/Ocean/Regulations/Fishing-Map/San-Francisco" target="_blank" rel="noopener">Point Sur 以北比目鱼规定</a> · <a href="https://montereybay.noaa.gov/visitor/seasons.html" target="_blank" rel="noopener">NOAA 季节生态</a></p></details>`);$('settings-audio').onclick=()=>{audio.init();audio.toggle();openSettings();};$('settings-music').onclick=()=>{audio.init();audio.toggleMusic();openSettings();};$('music-volume').oninput=()=>{audio.init();audio.setMusicVolume(Number($('music-volume').value));};$('settings-photo').onclick=()=>{closeModal();const a=document.createElement('a');a.href=$(focusActive?'fight-view':'world').toDataURL('image/png');a.download='santa-cruz-pixel.png';a.click();};if($('settings-rescue'))$('settings-rescue').onclick=()=>{closeModal();feedback(sim.rescue());persist();};}
function openCompass(){const n=sim.navigationInstruments();if(!n.compass)return;openModal('compass',heading('SHIP COMPASS','船用罗盘')+`<div class="gps-reading">${Math.round(n.heading)}°</div><p class="modal-desc">${sim.state.mode==='boat'?'船首':'面朝'}方位 · 北 0° / 东 90° / 南 180° / 西 270°</p>`);}
function openGPS(){const n=sim.navigationInstruments();if(!n.gps)return;const p=n.gpsPosition;openModal('gps',heading('GPS RECEIVER','当前位置')+`<div class="gps-reading">${p.lat.toFixed(5)}° N<br>${Math.abs(p.lon).toFixed(5)}° W</div><p class="modal-desc">航速 ${formatSpeed(sim.state.speed)}</p><p class="credits-note">地理坐标保留真实尺度。游戏外海航程采用 1:2 比例。</p>`);}
function openSounder(){if(!sim.navigationInstruments().sounder)return;const s=sim.state;openModal('sounder',heading('BOTTOM PROFILE','船下的起伏','沿船首方向前后各 164 ft · NOAA 地形参考')+`<canvas id="sounder-chart" class="map-canvas" width="540" height="240"></canvas><p class="credits-note">历史 MHW 地形网格约 68 ft 分辨率；空缺表示没有参考数据。</p>`);const c=$('sounder-chart'),x=c.getContext('2d'),samples=Array.from({length:81},(_,i)=>{const d=(i-40)*1.25;return depthInfoAt(s.boatX-Math.sin(s.heading)*d,s.boatZ-Math.cos(s.heading)*d).value;}),valid=samples.filter(Number.isFinite),max=Math.max(12,...valid)*1.2;x.fillStyle='#245f70';x.fillRect(0,0,540,240);x.strokeStyle='#bccc98';x.lineWidth=2;let previous=null;for(let i=0;i<samples.length;i++){const d=samples[i];if(!Number.isFinite(d)){previous=null;continue;}const px=20+i*6.25,py=30+d/max*180;if(previous){x.fillStyle='#a2a47b';x.beginPath();x.moveTo(previous.x,previous.y);x.lineTo(px,py);x.lineTo(px,220);x.lineTo(previous.x,220);x.closePath();x.fill();x.beginPath();x.moveTo(previous.x,previous.y);x.lineTo(px,py);x.stroke();}previous={x:px,y:py};}x.fillStyle='#fff1d5';x.font='12px monospace';x.fillText('-164 ft',20,17);x.fillText('BOAT',253,17);x.fillText('+164 ft',465,17);x.fillText(Number.isFinite(samples[40])?formatDepth(samples[40]):'—',279,40);x.setLineDash([3,3]);x.strokeStyle='#fff1d5';x.beginPath();x.moveTo(270,25);x.lineTo(270,217);x.stroke();}
for(const id of ['interact-btn','guide-btn']){const el=$(id);$('world-actions').append(el);el.classList.add('world-action');el.classList.remove('action-button');}
